package models

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	dmodel "github.com/sky-as-code/nikki-erp/common/dynamicmodel/model"
)

// The document numbers are stamped by the domain service before validation: served as auto-generated
// (server_assigned) so a form does not demand them, never auto_generated, which would erase the stamp.
func TestDocumentNumbersAreServerAssigned(t *testing.T) {
	requireBaseSchemasRegistered(t)

	numbers := map[string]func() *dmodel.ModelSchemaBuilder{
		StockTransferFieldTransferNumber: StockTransferSchemaBuilder,
		StockScrapFieldScrapNumber:       StockScrapSchemaBuilder,
	}
	for name, builder := range numbers {
		field, ok := builder().Build().Field(name)
		require.Truef(t, ok, "%s exists", name)
		assert.Truef(t, field.IsServerAssigned(), "%s is server_assigned", name)
		assert.Falsef(t, field.IsAutoGenerated(), "%s must not be auto_generated", name)
		assert.Truef(t, field.IsRequiredForCreate(), "%s stays required: its composite unique needs it", name)
	}
}
